//! Records the UI renders: what a show looks like once ops have been applied. The same shapes
//! come out of the app's local database (over IPC) and the cloud API (over REST).
//! Ids are UUID strings, generated by whoever creates the entity.

use serde::{Deserialize, Serialize};

use crate::sync::EntityKind;

/// What a member may do with a show.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[serde(rename_all = "snake_case")]
pub enum MemberRole {
    Owner,
    Editor,
    Commenter,
    Viewer,
}

impl MemberRole {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Owner => "owner",
            Self::Editor => "editor",
            Self::Commenter => "commenter",
            Self::Viewer => "viewer",
        }
    }

    pub fn parse(value: &str) -> Option<Self> {
        match value {
            "owner" => Some(Self::Owner),
            "editor" => Some(Self::Editor),
            "commenter" => Some(Self::Commenter),
            "viewer" => Some(Self::Viewer),
            _ => None,
        }
    }

    /// May this role apply an op on `entity`? Deleting the show itself is owner-only.
    pub fn may_edit(self, entity: EntityKind, deleting: bool) -> bool {
        match self {
            Self::Owner => true,
            Self::Editor => !(entity == EntityKind::Show && deleting),
            Self::Commenter => entity == EntityKind::Comment,
            Self::Viewer => false,
        }
    }

    /// Managing members and invites.
    pub fn may_manage(self) -> bool {
        self == Self::Owner
    }
}

fn owner() -> MemberRole {
    MemberRole::Owner
}

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct Show {
    pub id: String,
    pub name: String,
    pub time: i64,
    /// The signed-in user's role in this show (the owner of a purely local show).
    #[serde(default = "owner")]
    pub role: MemberRole,
}

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct ShowRole {
    pub id: String,
    pub show_id: String,
    pub name: String,
}

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct ScenarioLineComment {
    pub id: String,
    pub line_id: String,
    pub role_id: Option<String>,
    pub comment: String,
}

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct ScenarioLine {
    pub id: String,
    /// Fractional ordering key (see `crate::position`); compare as plain strings.
    pub position: String,
    pub name: String,
    pub note: String,
    pub duration: i64,
    pub absolute_time: Option<i64>,
}

/// A whole show: `lines` come sorted by `(position, id)`, nothing deleted is included.
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq)]
pub struct ShowDetails {
    pub show: Show,
    pub roles: Vec<ShowRole>,
    pub lines: Vec<ScenarioLine>,
    pub comments: Vec<ScenarioLineComment>,
    /// The last change included (0 for a purely local show that never synced).
    #[serde(default)]
    pub rev: i64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn role_permissions() {
        use EntityKind::*;
        assert!(MemberRole::Owner.may_edit(Show, true));
        assert!(!MemberRole::Editor.may_edit(Show, true));
        assert!(MemberRole::Editor.may_edit(Show, false) && MemberRole::Editor.may_edit(Line, true));
        assert!(MemberRole::Commenter.may_edit(Comment, false));
        assert!(!MemberRole::Commenter.may_edit(Line, false) && !MemberRole::Commenter.may_edit(Role, false));
        for entity in [Show, Role, Line, Comment] {
            assert!(!MemberRole::Viewer.may_edit(entity, false));
        }
        assert!(MemberRole::Owner.may_manage() && !MemberRole::Editor.may_manage());
        assert_eq!(MemberRole::parse("commenter"), Some(MemberRole::Commenter));
        assert_eq!(MemberRole::parse("admin"), None);
    }
}
